import { tv, type VariantProps } from "@/lib/beton/tv";

export const featureGrid = tv({
  slots: {
    list: "grid gap-6",
    item: "flex h-full flex-col gap-3 border-3 border-border bg-raised p-6 shadow-sm",
    icon: "flex size-12 shrink-0 items-center justify-center border-3 border-border bg-secondary",
    itemTitle: "font-display text-h4 font-extrabold text-foreground",
    itemDescription: "text-pretty text-foreground",
  },
  variants: {
    columns: {
      2: { list: "sm:grid-cols-2" },
      3: { list: "sm:grid-cols-2 lg:grid-cols-3" },
      4: { list: "sm:grid-cols-2 lg:grid-cols-4" },
    },
  },
  defaultVariants: {
    columns: 3,
  },
});

export type FeatureGridVariants = VariantProps<typeof featureGrid>;

import { featureGrid, type FeatureGridVariants } from "@/lib/beton/recipes/feature-grid.recipe";
import type { ComponentProps, ReactNode } from "react";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface Feature {
  /** What the feature is called. */
  title: ReactNode;
  /** One or two sentences on what it does. */
  description: ReactNode;
  /** A mark above the title. Decorative: it is hidden from screen readers. */
  icon?: ReactNode;
  /** Makes the whole card a link. */
  href?: string;
}

export interface FeatureGridProps extends Omit<SectionProps, "children">, FeatureGridVariants {
  /** The features, in order. */
  features: Feature[];
  /** The heading level of each feature. One below the section heading. */
  itemHeadingLevel?: 3 | 4 | 5;
  /** Classes for the grid itself. */
  listClassName?: string;
}

/** A grid of what a thing does, one card per feature. */
export function FeatureGrid({
  features,
  columns = 3,
  itemHeadingLevel = 3,
  listClassName,
  ...props
}: FeatureGridProps) {
  const styles = featureGrid({ columns });
  const Heading = `h${itemHeadingLevel}` as const;

  return (
    <Section {...props}>
      <ul className={styles.list({ class: listClassName })}>
        {features.map((feature, index) => (
          <li key={index} className={styles.item()}>
            {feature.icon ? (
              <span aria-hidden="true" className={styles.icon()}>
                {feature.icon}
              </span>
            ) : null}
            <Heading className={styles.itemTitle()}>
              {feature.href ? <a href={feature.href}>{feature.title}</a> : feature.title}
            </Heading>
            <p className={styles.itemDescription()}>{feature.description}</p>
          </li>
        ))}
      </ul>
    </Section>
  );
}

export type FeatureGridItemProps = ComponentProps<"li">;
